document.querySelectorAll('form[data-demo]').forEach(form=>{form.addEventListener('submit',e=>{e.preventDefault();const result=form.querySelector('.status'); result.textContent='Your demo brief is ready. Nothing has been sent or booked.'; const summary=document.createElement('div');summary.className='summary'; for(const [key,value] of new FormData(form)){const p=document.createElement('p');p.textContent=key+': '+value;summary.appendChild(p)}const old=form.querySelector('.summary');if(old)old.remove();result.after(summary)});form.addEventListener('reset',()=>{form.querySelector('.status').textContent='Demo brief cleared.';form.querySelector('.summary')?.remove()})});
const progress=document.createElement('div');progress.className='scroll-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);const topLink=document.createElement('a');topLink.className='back-top';topLink.href='#top';topLink.setAttribute('aria-label','Back to top');topLink.textContent='↑';document.body.append(topLink);function updateScroll(){const max=document.documentElement.scrollHeight-innerHeight;progress.style.width=(max>0?scrollY/max*100:0)+'%';topLink.classList.toggle('visible',scrollY>600)}addEventListener('scroll',updateScroll,{passive:true});updateScroll();
